use serde_json::{json,Value};use std::{fs,path::Path,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/loose-g1-finish174";
fn main(){let r=Path::new(R);let a:Value=serde_json::from_slice(&fs::read(r.join("analysis.json")).unwrap()).unwrap();let ids:Value=serde_json::from_slice(&fs::read(r.join("identities.json")).unwrap()).unwrap();let mut rows=Vec::new();for v in ["accepted","OFF","ON"]{let p=&a["diagnostics"]["profiles"][format!("cycles-1x2-w32-{v}")];let symbols=p["symbols"].as_array().unwrap().iter().filter(|s|s["symbol"].as_str().unwrap().contains("stream_g1_impl")).collect::<Vec<_>>();assert_eq!(symbols.len(),1);let name=symbols[0]["symbol"].as_str().unwrap();let bin=ids[v]["binary"].as_str().unwrap();let out=Command::new("objdump").args(["-d","--no-show-raw-insn",&format!("--disassemble={name}"),bin]).output().unwrap();assert!(out.status.success());let text=String::from_utf8(out.stdout).unwrap();let lines=text.lines().filter_map(|l|{let (addr,asm)=l.trim().split_once(':')?;if !addr.is_empty()&&addr.bytes().all(|b|b.is_ascii_hexdigit())&&!asm.trim().is_empty(){Some(asm.trim())}else{None}}).collect::<Vec<_>>();assert!(lines.len()>1000);fs::write(r.join(format!("g1-{v}.asm.txt")),&text).unwrap();rows.push(json!({"variant":v,"binary":bin,"binary_sha256":ids[v]["sha256"],"symbol":name,"demangled":rustc_demangle::demangle(name).to_string(),"instruction_sites":lines.len(),"IFMA_sites":lines.iter().filter(|l|l.starts_with("vpmadd52")).count(),"RSP_address_sites":lines.iter().filter(|l|l.contains("(%rsp")||l.contains(",%rsp,")).count(),"calls":lines.iter().filter(|l|l.starts_with("call")).count(),"stack_subtractions":lines.iter().filter(|l|l.starts_with("sub")&&l.ends_with("%rsp")).collect::<Vec<_>>() }));}fs::write(r.join("codegen.json"),serde_json::to_vec_pretty(&json!({"scope":"offline static symbol sites;not retired instruction counts,spill counts or removable wall time","rows":rows})).unwrap()).unwrap();}
